def hidden_rule_fn(state):
    n = len(state)
    # Check if n is prime
    def is_prime(x):
        if x < 2:
            return False
        for i in range(2, int(x**0.5) + 1):
            if x % i == 0:
                return False
        return True

    if is_prime(n):
        # Prime position: XOR of last two elements mod 7
        new_val = (state[-2] ^ state[-1]) % 7
    else:
        # Non-prime position: sum of last two + 3 mod 7
        new_val = (state[-2] + state[-1] + 3) % 7

    return state + [new_val]
